<?php require __DIR__.'/bootstrap.php'; $ref=(string)($_GET['reference']??$_GET['trxref']??''); if(!$ref){site_header('Payment status');echo '<section class="content"><div class="alert error">Missing payment reference.</div><a class="button" href="track.php">Track an order</a></section>';site_footer();exit;} $secret=(string)cfg('paystack_secret_key','');$ch=curl_init('https://api.paystack.co/transaction/verify/'.rawurlencode($ref));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$response=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$response,true);$orders=read_json('orders.json',[]);$found=false;$order=null;foreach($orders as &$o){if(($o['reference']??'')===$ref){$found=true;$order=&$o;if($status>=200&&$status<300&&!empty($data['status'])&&($data['data']['status']??'')==='success'&&strtoupper((string)($data['data']['currency']??''))==='NGN'&&(int)($data['data']['amount']??0)===(int)round(((float)$o['total'])*100)){if(($o['payment_status']??'')!=='paid'){$o['payment_status']='paid';$o['payment_reference']=(string)($data['data']['reference']??$ref);$o['status']='Order Confirmed';$o['timeline'][]=['status'=>'Order Confirmed','at'=>date(DATE_ATOM)];$o['paid_at']=date(DATE_ATOM);$sendOrder=$o;} }break;}}unset($o);if($found)write_json('orders.json',$orders);if(isset($sendOrder)){notify_order($sendOrder);add_notification('Payment verified','Payment verified for order '.$ref.'.','payment',$ref);} site_header('Payment status');echo '<section class="content"><div class="card-panel">';if(isset($sendOrder)){echo '<div class="alert success">Payment verified successfully. Your order is confirmed.</div><h1>Thank you for choosing Bakery Bake.</h1><p>Your order reference is <strong>'.e($ref).'</strong>. Order details have been submitted for email delivery.</p>';}elseif($found&&($order['payment_status']??'')==='paid'){echo '<div class="alert success">This payment has already been verified.</div><h1>Your order is confirmed.</h1><p>Reference: <strong>'.e($ref).'</strong></p>';}elseif($found){echo '<div class="alert">We have not yet verified this payment. Do not pay again immediately. Check your order status in a moment or contact the bakery with your order reference.</div><h1>Payment status pending</h1><p>Reference: <strong>'.e($ref).'</strong></p>';}else{echo '<div class="alert error">We could not find an order matching this payment reference.</div>';}echo '<div class="hero-actions"><a class="button" href="track.php?reference='.urlencode($ref).'">Track your order</a><a class="button button-outline" href="cakes.php">Continue shopping</a></div></div></section>';site_footer(); ?>
